def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def prime_factorization(num):
    factors = {}
    d = 2
    temp = num
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

# Task 1: Verify n=0, 2, 6
def check_solution(n):
    if n < 0:
        return "Invalid n"

    Dn = D(n)
    if Dn == 0:
        return "D(n) is zero, skip."

    factors_Dn = prime_factorization(Dn)

    # 20^(n+1) = 2^(2n+2) * 5^(n+1)
    max_power_2 = 2 * n + 2
    max_power_5 = n + 1

    is_solution = True

    # Check non-2, 5 prime factors
    for p in factors_Dn:
        if p != 2 and p != 5:
            is_solution = False
            break

    if not is_solution:
        return f"Failed: Has non-2/5 prime factor {p}."

    # Check 2 exponent
    v2 = factors_Dn.get(2, 0)
    if v2 > max_power_2:
        is_solution = False

    # Check 5 exponent
    v5 = factors_Dn.get(5, 0)
    if v5 > max_power_5:
        is_solution = False

    if is_solution:
        return f"Verified: n={n} is a solution. D({n}) = {Dn}. Prime factors match $2^{{{max_power_2}}} 5^{{{max_power_5}}}$ or fewer."
    else:
        return f"Failed: Exponent condition violated. D({n}) = {Dn}. Max allowed exponents: 2={max_power_2}, 5={max_power_5}."


# Verification for n=0, 2, 6
results_verification = {}
for n in [0, 2, 6]:
    results_verification[n] = check_solution(n)

print("--- Verification Results (n=0, 2, 6) ---")
for n, res in results_verification.items():
    print(f"n={n}: {res}")

# Task 2: Brute force search for n in [16, 30]
solutions_found = []
print("\n--- Brute Force Search (n=16 to 30) ---")
for n in range(16, 31):
    Dn = D(n)
    factors_Dn = prime_factorization(Dn)

    max_power_2 = 2 * n + 2
    max_power_5 = n + 1

    is_solution = True

    # Check non-2, 5 prime factors
    for p in factors_Dn:
        if p != 2 and p != 5:
            is_solution = False
            break

    if not is_solution:
        # Skip detailed print if it fails the primary condition
        continue

    # Check exponents
    v2 = factors_Dn.get(2, 0)
    v5 = factors_Dn.get(5, 0)

    if v2 <= max_power_2 and v5 <= max_power_5:
        solutions_found.append({
            'n': n, 
            'Dn': Dn, 
            'factors': factors_Dn
        })
        print(f"Found solution n={n}!")

print("\n--- Summary of New Solutions ---")
if solutions_found:
    for sol in solutions_found:
        print(f"n={sol['n']}: D(n) = {sol['Dn']}. Prime factorization: {sol['factors']}")
else:
    print("No new solutions found in the range [16, 30].")
